/bin/zsh -lc "python3 -c 'import json,itertools
x=json.load(open(\"input.json\"))
def reach(s,t,removed=()):
 seen={s}; todo=[s]
 while todo:
  u=todo.pop()
  for e in x[\"edges\"]:
   if e[\"id\"] not in removed and e[\"source\"]==u and e[\"target\"] not in seen:
    seen.add(e[\"target\"]);todo.append(e[\"target\"])
 return t in seen
rp=[];ap=[]
for p in sorted(x[\"probes\"],key=lambda p:p[\"id\"]):
 if reach(p[\"source\"],p[\"target\"]):
  rp.append(p[\"id\"])
  if p[\"signed\"] is True and p[\"audience\"]==\"control\" and p[\"tenant\"]==p[\"resource_tenant\"] and x[\"now\"]<p[\"expires\"] and p[\"key\"] not in x[\"revoked_keys\"]:ap.append(p[\"id\"])
es=sorted([e for e in x[\"edges\"] if e[\"removable\"]],key=lambda e:e[\"id\"]);best=None
for bits in itertools.product((0,1),repeat=len(es)):
 rem=[e[\"id\"] for e,b in zip(es,bits) if b]
 if any(reach(s,t,rem) for s,t in x[\"forbidden\"]) or not all(reach(s,t,rem) for s,t in x[\"required\"]):continue
 score=(sum(e[\"cost\"] for e,b in zip(es,bits) if b),len(rem),rem)
 if best is None or score<best:best=score
print(json.dumps(dict(reachable_probes=rp,authorized_probes=ap,repair_edges=best[2],repair_cost=best[0])))'"

